/**
 * Bitmap text for the watch: 2-bit grayscale CJK atlas generated by
 * tools/genfont.py, drawn with a fixed advance so the host can pre-wrap lines
 * to the exact pixel budget.
 *
 * Header-only and templated so the same call draws straight to the panel
 * (M5GFX) and into a sprite (M5Canvas).
 */

#pragma once

#include <M5GFX.h>
#include <stdint.h>

#include "assets/font_cn.h"

namespace text {

constexpr int kWide = 28;    // advance of a full-width glyph, px
constexpr int kAscii = 18;   // advance of an ASCII glyph, px
constexpr int kLineHeight = 34;

namespace detail {

inline uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return static_cast<uint16_t>(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

inline uint16_t mix(uint16_t from, uint16_t to, int num, int den) {
  const int fr = (from >> 11) & 0x1F, fg = (from >> 5) & 0x3F, fb = from & 0x1F;
  const int tr = (to >> 11) & 0x1F, tg = (to >> 5) & 0x3F, tb = to & 0x1F;
  const int r = fr + (tr - fr) * num / den;
  const int g = fg + (tg - fg) * num / den;
  const int b = fb + (tb - fb) * num / den;
  return static_cast<uint16_t>((r << 11) | (g << 5) | b);
}

/** Decode one UTF-8 code point and advance the cursor. */
inline uint32_t decode(const char*& cursor) {
  const uint8_t first = static_cast<uint8_t>(*cursor);
  if (first == 0) return 0;
  cursor++;
  if (first < 0x80) return first;
  int extra = 0;
  uint32_t value = 0;
  if ((first & 0xE0) == 0xC0) {
    value = first & 0x1F;
    extra = 1;
  } else if ((first & 0xF0) == 0xE0) {
    value = first & 0x0F;
    extra = 2;
  } else if ((first & 0xF8) == 0xF0) {
    value = first & 0x07;
    extra = 3;
  } else {
    return 0xFFFD;
  }
  for (int i = 0; i < extra; i++) {
    const uint8_t next = static_cast<uint8_t>(*cursor);
    if ((next & 0xC0) != 0x80) return 0xFFFD;
    value = (value << 6) | (next & 0x3F);
    cursor++;
  }
  return value;
}

/** Binary-search the atlas. */
inline const uint8_t* find(uint32_t codepoint) {
  int low = 0;
  int high = FONT_GLYPH_COUNT - 1;
  while (low <= high) {
    const int mid = (low + high) / 2;
    const uint16_t value = FONT_CODEPOINTS[mid];
    if (value == codepoint) return FONT_GLYPHS[mid];
    if (value < codepoint) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return nullptr;
}

inline uint8_t level_at(const uint8_t* glyph, int x, int y) {
  const int index = y * (FONT_CELL_W * 2 / 8) + (x * 2) / 8;
  const int shift = 6 - ((x * 2) % 8);
  return (glyph[index] >> shift) & 0x03;
}

}  // namespace detail

/** Pixel width of a UTF-8 string at the on-device metrics. */
inline int width(const char* utf8) {
  int total = 0;
  const char* cursor = utf8;
  while (*cursor != 0) {
    const uint32_t codepoint = detail::decode(cursor);
    if (codepoint == 0) break;
    total += codepoint < 0x80 ? kAscii : kWide;
  }
  return total;
}

/**
 * Draw one line of UTF-8 text.
 * @param g target surface (M5GFX panel or M5Canvas sprite)
 */
template <typename Target>
inline void draw(Target& g, int x, int y, const char* utf8, uint16_t fg, uint16_t bg) {
  uint16_t palette[4];
  palette[0] = bg;
  palette[3] = fg;
  palette[1] = detail::mix(bg, fg, 1, 3);
  palette[2] = detail::mix(bg, fg, 2, 3);

  uint16_t pixels[FONT_CELL_W * FONT_CELL_H];

  const char* cursor = utf8;
  while (*cursor != 0) {
    const uint32_t codepoint = detail::decode(cursor);
    if (codepoint == 0) break;
    const int advance = codepoint < 0x80 ? kAscii : kWide;
    const uint8_t* glyph = detail::find(codepoint);
    if (glyph == nullptr) {
      x += advance;
      continue;
    }
    // pushImage(uint16_t*) byte-swaps on its way to the panel; pre-swapping
    // cancels it so the glyphs keep the palette colours
    int index = 0;
    for (int gy = 0; gy < FONT_CELL_H; gy++) {
      for (int gx = 0; gx < advance; gx++) {
        const uint16_t colour = palette[detail::level_at(glyph, gx, gy)];
        pixels[index++] = static_cast<uint16_t>((colour >> 8) | (colour << 8));
      }
    }
    g.pushImage(x, y, advance, FONT_CELL_H, pixels);
    x += advance;
  }
}

/**
 * Wrap UTF-8 text into at most `maxLines` lines of `maxWidth` pixels.
 * @returns the number of lines written.
 */
inline int wrap(const char* utf8, int maxWidth, char out[][64], int maxLines) {
  int line = 0;
  int used = 0;
  int column = 0;
  out[0][0] = 0;
  const char* cursor = utf8;
  while (*cursor != 0 && line < maxLines) {
    const char* start = cursor;
    const uint32_t codepoint = detail::decode(cursor);
    if (codepoint == 0) break;
    const int advance = codepoint < 0x80 ? kAscii : kWide;
    if (used + advance > maxWidth && column > 0) {
      out[line][column] = 0;
      line++;
      if (line >= maxLines) break;
      column = 0;
      used = 0;
      out[line][0] = 0;
    }
    const size_t bytes = static_cast<size_t>(cursor - start);
    if (column + bytes < 63) {
      memcpy(out[line] + column, start, bytes);
      column += static_cast<int>(bytes);
      out[line][column] = 0;
    }
    used += advance;
  }
  return line < maxLines ? line + 1 : maxLines;
}

/** Draw one line centred on `cx`. */
template <typename Target>
inline void drawCentered(Target& g, int cx, int y, const char* utf8, uint16_t fg, uint16_t bg) {
  draw(g, cx - width(utf8) / 2, y, utf8, fg, bg);
}

}  // namespace text
